// Independent reviewed mechanics challenge; not part of the frozen benchmark.
import fs from 'node:fs';
import crypto from 'node:crypto';
import {chromium} from '/validator/node_modules/playwright/index.mjs';
import {bridgeAdapter} from '/validator/bridge_adapter.mjs';
const hash = value => crypto.createHash('sha256').update(value).digest('hex');
const html = fs.readFileSync('/input/game.html','utf8');
const config = JSON.parse(fs.readFileSync('/input/config.json','utf8'));
const checks = [], snapshots = [], evidence = [];
const record = (name, condition, detail) => checks.push({name,passed:condition,detail});
const same = (a,b) => JSON.stringify(a) === JSON.stringify(b);
function observe(name,snapshot){snapshots.push({name,snapshot});return snapshot;}
const browser = await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_EXECUTABLE || undefined,args:['--no-sandbox','--disable-dev-shm-usage','--disable-background-networking','--alsa-output-device=null']});
for(const width of [1280,390]){
 const touch=width===390, context=await browser.newContext({viewport:{width,height:touch?844:800},hasTouch:touch,isMobile:touch,acceptDownloads:false,serviceWorkers:'block'});
 await context.tracing.start({screenshots:true,snapshots:true,sources:false});
 const page=await context.newPage();page.setDefaultTimeout(5000);
 const errors=[],network=[];page.on('pageerror',e=>errors.push(e.message));let initial=true;
 await context.route('**/*',async route=>{if(initial && route.request().url()==='http://review.invalid/index.html' && route.request().isNavigationRequest()){initial=false;await route.fulfill({contentType:'text/html',body:html,headers:{'Content-Security-Policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data: blob:; media-src data: blob:; connect-src 'none'; frame-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'"}});}else{network.push(route.request().url().slice(0,300));await route.abort();}});
 try{
  await page.goto('http://review.invalid/index.html');
  const pointer=selector=>touch?page.locator(selector).tap():page.locator(selector).click();
  const rawPointer=async selector=>{const box=await page.locator(selector).boundingBox();if(!box)throw new Error('Visible control missing: '+selector);const x=box.x+box.width/2,y=box.y+box.height/2;return touch?page.touchscreen.tap(x,y):page.mouse.click(x,y);};
  await pointer('[data-testid="start"]');
  const bridge=bridgeAdapter(page);
  const get=name=>bridge.snapshot().then(x=>observe(`${name}:${width}`,x));
  let state=await get('initial');
  record(`initial:${width}`,state.phase==='playing' && state.moves===0 && state.beacons.length===config.beacons && state.beacons.every(x=>x===false),{observed:state});
  await page.waitForTimeout(200);let idle=await get('idle');record(`no-time-progress:${width}`,same(state,idle),{actual_idle_ms:200});
  const activate=async index=>touch?pointer(`[data-testid="beacon-${index+1}"]`):page.keyboard.press(String(index+1));
  await activate(0);state=await get('first-toggle');
  record(`only-selected-toggle:${width}`,state.moves===1 && state.beacons[0]===true && state.beacons.slice(1).every(x=>x===false),{observed:state,real_input:touch?'tap':'key1'});
  await activate(0);state=await get('toggle-back');
  record(`selected-toggle-reversible:${width}`,state.moves===2 && state.beacons.every(x=>x===false) && state.phase==='playing',{observed:state});
  if(!touch){await page.keyboard.press('9');let invalid=await get('invalid-key');record(`unmapped-key-ignored:${width}`,same(state,invalid),{key:'9'});}
  for(let index=0;index<config.beacons;index++)await activate(index);
  state=await get('legal-win');
  record(`legal-win:${width}`,state.phase==='won' && state.moves===config.beacons+2 && state.beacons.every(x=>x===true),{ordinary_inputs:config.beacons,observed:state});
  fs.writeFileSync(`/evidence/win-${width}.png`,await page.screenshot());
  if(touch)await rawPointer('[data-testid="beacon-1"]');else await activate(0);let terminal=await get('terminal-input');
  record(`terminal-input-immutable:${width}`,same(state,terminal),{actual_real_input:true});
  await rawPointer('[data-testid="beacon-2"]');terminal=await get('terminal-pointer');
  record(`terminal-pointer-immutable:${width}`,same(state,terminal),{actual_real_input:true});
  await pointer('[data-testid="restart"]');state=await get('restart');
  record(`restart-clears-progress:${width}`,state.phase==='playing' && state.moves===0 && state.beacons.every(x=>x===false),{observed:state});
  if(touch){let layout=await page.evaluate(()=>({viewport:innerWidth,scroll:document.documentElement.scrollWidth}));record(`mobile-no-overflow:${width}`,layout.scroll<=layout.viewport+2,layout);}
 }catch(error){record(`challenge-error:${width}`,false,{message:String(error.message).slice(0,1000)});}
 finally{
  record(`uncaught-errors:${width}`,errors.length===0,{errors});record(`network-attempts:${width}`,network.length===0,{network});
  await context.tracing.stop({path:`/evidence/trace-${width}.zip`});await context.close();
 }
}
for(const name of fs.readdirSync('/evidence').sort()){const data=fs.readFileSync('/evidence/'+name);evidence.push({path:name,sha256:hash(data),bytes:data.length});}
process.stdout.write(JSON.stringify({schema_version:1,scope:'Independent external mechanics challenge in isolated Chromium; frozen benchmark result unchanged',passed:checks.every(x=>x.passed),html_sha256:hash(Buffer.from(html)),validator_image:config.image,review_script_sha256:hash(fs.readFileSync('/review/challenge.mjs')),browser_version:browser.version(),checks,snapshots,evidence_files:evidence}));
await browser.close();

