  state=await get('three-misses');record(`three-misses-lose:${width}`,state.phase==='lost' && state.score===0 && state.misses===3 && state.attemptsRemaining===0,{observed:state});
  fs.writeFileSync(`/evidence/lost-${width}.png`,await page.screenshot({fullPage:true}));
